<?php require_once __DIR__.'/../../includes/auth.php';requireSuperAdmin();require_once __DIR__.'/../../includes/functions.php';$eventId=(int)($_GET['event_id']??0);$events=$pdo->query("SELECT id,name,event_code,status FROM events ORDER BY name")->fetchAll();$rows=[];if($eventId){$q=$pdo->prepare("SELECT c.id,c.name,c.category_code,cat.name category_name,COALESCE(SUM(v.vote_count),0) votes,COALESCE(SUM(t.amount),0) revenue FROM contestants c JOIN categories cat ON cat.id=c.category_id LEFT JOIN votes v ON v.contestant_id=c.id LEFT JOIN transactions t ON t.id=v.transaction_id AND t.status='Successful' WHERE c.event_id=? GROUP BY c.id,c.name,c.category_code,cat.name ORDER BY cat.display_order,cat.name,votes DESC,c.name");$q->execute([$eventId]);$rows=$q->fetchAll();}$pageTitle='Live Results';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';?><main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><div class="d-flex justify-content-between mb-4"><div><span class="section-kicker">LIVE VOTING</span><h1 class="page-title">Live Results</h1><p class="page-subtitle">Successful payments only contribute to votes.</p></div><span class="badge bg-success align-self-start">LIVE</span></div><div class="panel mb-4"><div class="panel-body"><form class="row g-3 align-items-end"><div class="col-md-8"><label class="form-label">Event</label><select name="event_id" class="form-select" required><option value="">Select event</option><?php foreach($events as $e):?><option value="<?=$e['id']?>" <?=$eventId==$e['id']?'selected':''?>><?=e($e['name'])?> — <?=e($e['event_code'])?></option><?php endforeach;?></select></div><div class="col-md-4"><button class="btn btn-primary w-100">View Results</button></div></form></div></div><?php if($eventId):?><div class="panel"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Category</th><th>Contestant</th><th>Code</th><th>Votes</th><th>Revenue</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['category_name'])?></td><td><strong><?=e($r['name'])?></strong></td><td><span class="ticket-code"><?=e($r['category_code'])?> / <?=e($r['id'])?></span></td><td class="fw-bold"><?=number_format((int)$r['votes'])?></td><td>GHS <?=number_format((float)$r['revenue'],2)?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center py-5 text-muted">No contestants/results yet.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?></section></main><?php require __DIR__.'/../../includes/footer.php';?>
